    els.contractGoal.textContent=state.contractGoal;els.contractTarget.textContent=state.hits>=30?'pirate bomber':'TIE scout';let p=Math.min(100,state.contractHits/state.contractGoal*100);els.contractProgress.textContent=state.contractHits+' / '+state.contractGoal;els.contractBar.style.width=p+'%';els.reward.textContent=number(25+state.contractGoal*2);
