(() => {
  'use strict';
  const SAVE_KEY = 'outer-rim-flight-v1';
  const upgrades = [
    {id:'droid',name:'Astromech crew',icon:'◉',desc:'Repair droids trade spare parts for credits.',cost:25,growth:1.16,rate:1,kind:'rate'},
    {id:'blaster',name:'Blaster tuning',icon:'ϟ',desc:'Overcharge your cannons for a heavier hit.',cost:50,growth:1.17,rate:1,kind:'click'},
    {id:'squadron',name:'Wing squadron',icon:'✦',desc:'A flight of pilots brings in steady bounties.',cost:160,growth:1.19,rate:5,kind:'rate'},
    {id:'trade',name:'Hyperspace routes',icon:'⌁',desc:'Open a profitable lane through the Outer Rim.',cost:700,growth:1.2,rate:20,kind:'rate'}
  ];
  const fresh = () => ({credits:0,hits:0,bestStreak:0,combo:1,clickPower:1,passive:0,owned:{},contractHits:0,contractGoal:10,flightSeconds:0,buyMode:1,lastSeen:Date.now(),sound:false});
  let state=fresh(), comboExpiry=0, toastTimer, passiveFraction=0, audio;
  try { const saved=JSON.parse(localStorage.getItem(SAVE_KEY)); if(saved&&saved.v===1){state={...fresh(),...saved.data,owned:{...fresh().owned,...saved.data.owned}};} } catch (_) {}
  const $=id=>document.getElementById(id);
  const els={scene:$('scene'),target:$('fighterTarget'),fire:$('fireButton'),credits:$('creditTotal'),header:$('headerCredits'),income:$('incomeRate'),click:$('clickValue'),bounty:$('bountyValue'),combo:$('comboValue'),comboMeter:$('comboMeter'),hits:$('statHits'),best:$('statBestStreak'),time:$('statTime'),rank:$('rankName'),rankText:$('rankProgressText'),rankBar:$('rankProgressBar'),contractTarget:$('contractTarget'),contractGoal:$('contractGoal'),contractProgress:$('contractProgressText'),contractBar:$('contractProgressBar'),reward:$('contractReward'),hp:$('hpBars'),threat:$('threatLevel'),list:$('upgradeList'),buyMode:$('buyMode'),intel:$('intelText'),blaster:$('blasterMeter'),toast:$('toast'),modal:$('offlineModal'),offlineAmount:$('offlineAmount'),collect:$('collectOffline'),sound:$('soundToggle')};
  function rate(){return upgrades.reduce((n,u)=>n+(state.owned[u.id]||0)*(u.kind==='rate'?u.rate:0),0)}
  function clickPower(){return 1+(state.owned.blaster||0)}
  function costAt(u,n){return Math.ceil(u.cost*Math.pow(u.growth,n))}
  function buyCost(u,count){let total=0,owned=state.owned[u.id]||0;for(let i=0;i<count;i++)total+=costAt(u,owned+i);return total}
  function save(){state.lastSeen=Date.now();try{localStorage.setItem(SAVE_KEY,JSON.stringify({v:1,data:state}))}catch(_){}}
  function number(n){return Math.floor(n).toLocaleString('en-US')}
  function render(){
    const r=rate();els.credits.textContent=number(state.credits);els.header.textContent=number(state.credits);els.income.textContent=r%1?r.toFixed(1):number(r);els.click.textContent=number(clickPower()*state.combo);els.bounty.textContent='+'+number(clickPower()*state.combo);els.combo.textContent='x'+state.combo;els.hits.textContent=number(state.hits);els.best.innerHTML=state.bestStreak+'<span class="stat-unit">×</span>';
    const rank=Math.floor(state.hits/100),rankNames=['FLIGHT CADET','WINGMAN','SQUADRON LEAD','ACE PILOT','ROGUE LEGEND'];els.rank.textContent=rankNames[Math.min(rank,rankNames.length-1)];let xp=state.hits%100;els.rankText.textContent=xp+' / 100 XP';els.rankBar.style.width=xp+'%';els.threat.textContent='LVL '+String(1+Math.floor(state.hits/25)).padStart(2,'0');
    els.contractGoal.textContent=state.contractGoal;els.contractTarget.textContent=state.hits>=30?'pirate bomber':'TIE scout';let p=Math.min(100,state.contractHits/state.contractGoal*100);els.contractProgress.textContent=state.contractHits+' / '+state.contractGoal;els.contractBar.style.width=p+'%';els.reward.textContent=number(25+state.contractGoal*2);
    els.hp.querySelectorAll('i').forEach((el,i)=>el.classList.toggle('filled',i<5-(state.hits%5||0)));els.blaster.style.width=(100-(state.hits%8)*8)+'%';$('blasterStatus').textContent=state.hits%8===7?'CHARGING':'READY';
    $('targetName').textContent=state.hits>=30?'PIRATE BOMBER':'TIE SCOUT';$('targetWrap').setAttribute('aria-label','Target: '+(state.hits>=30?'pirate bomber':'TIE scout'));
    els.comboMeter.style.width=(Math.max(0,(comboExpiry-Date.now())/900)*100)+'%';els.list.innerHTML='';
    upgrades.forEach(u=>{const owned=state.owned[u.id]||0,cost=buyCost(u,state.buyMode),enough=state.credits>=cost,card=document.createElement('article');card.className='upgrade-card'+(enough?' affordable':'');card.innerHTML=`<div class="upgrade-icon" aria-hidden="true">${u.icon}</div><div><div class="upgrade-title">${u.name}</div><div class="upgrade-desc">${u.desc}</div><div class="upgrade-owned">OWNED <b>${owned}</b> · ${u.kind==='rate'?'+'+u.rate+' / sec':'+'+u.rate+' / click'}</div></div><button class="upgrade-buy" type="button" ${enough?'':'disabled'} aria-label="Buy ${u.name} for ${number(cost)} credits">BUY<span class="upgrade-cost">◈ ${number(cost)}</span></button>`;card.querySelector('button').addEventListener('click',()=>purchase(u));els.list.appendChild(card)});
    els.buyMode.innerHTML=`BUY <b>x${state.buyMode}</b>`;els.buyMode.setAttribute('aria-label','Change buy quantity; currently '+state.buyMode);$('statTime').textContent=String(Math.floor(state.flightSeconds/60)).padStart(2,'0')+':'+String(state.flightSeconds%60).padStart(2,'0');
  }
